-- Ikon kategori Pizza Snack Play
-- Dibuat oleh scripts/generate-category-icons.mjs — jangan disunting tangan.
--
-- Mengisi kolom `categories.image` dengan data URI PNG 256x256
-- hasil memanggang scripts/category-icons.html.
--
-- Dicocokkan lewat `slug`, bukan `id`: slug punya indeks unik
-- (`idx_categories_slug`), sedangkan nomor id bisa berbeda antara database
-- lokal dan produksi. Karena itu perintah ini idempoten — aman diulang.
--
-- Jalankan:
--   bunx wrangler d1 execute pizza-snack-play --local  --file=./scripts/sql/kategori-icons.sql
--   bunx wrangler d1 execute pizza-snack-play --remote --file=./scripts/sql/kategori-icons.sql
--
-- Ukuran terbesar di bawah: 43.4 KB base64 (batas aplikasi 1000 KB).

-- ── Gorengan ────────────────────────────────────────────────
UPDATE `categories` SET `image` = 'data:image/png;base64,' WHERE `slug` = 'gorengan';

-- ── Kukusan ─────────────────────────────────────────────────
UPDATE `categories` SET `image` = 'data:image/png;base64,' WHERE `slug` = 'kukusan';

-- ── Rebusan ─────────────────────────────────────────────────
UPDATE `categories` SET `image` = 'data:image/png;base64,' WHERE `slug` = 'rebusan';

-- ── Panggangan ──────────────────────────────────────────────
UPDATE `categories` SET `image` = 'data:image/png;base64,' WHERE `slug` = 'panggangan';

-- ── Buah Segar ──────────────────────────────────────────────
UPDATE `categories` SET `image` = 'data:image/png;base64,' WHERE `slug` = 'buah-segar';

-- ── Roti/Bakery ─────────────────────────────────────────────
UPDATE `categories` SET `image` = 'data:image/png;base64,' WHERE `slug` = 'roti-bakery';

-- ── Kue Tradisional ─────────────────────────────────────────
UPDATE `categories` SET `image` = 'data:image/png;base64,' WHERE `slug` = 'kue-tradisional';

-- ── Lainnya ─────────────────────────────────────────────────
UPDATE `categories` SET `image` = 'data:image/png;base64,' WHERE `slug` = 'lainnya';
